42	}
43	
44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	} as const satisfies Record<string, number>;
55	
56	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
57	
58	const basePremiumFor = (item: Item): number =>
59	  BASE_PREMIUMS[item.type as InsurableItemType];
60	
61	const sumBasePremiums = (items: Item[]): number =>
62	  items.reduce((sum, item) => sum + basePremiumFor(item), 0);
63	
64	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
65	// rounded, intermediate amounts stay fractional.
66	const roundInMHPCOsFavour = Math.ceil;
67	
68	const quotePremium = (items: Item[]): number => {
69	  const basePremium = sumBasePremiums(items);
70	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
71	  return roundInMHPCOsFavour(
72	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
73	  );
74	};
75	
76	export const runScenario = (scenario: Scenario): ScenarioResults => ({
77	  results: scenario.steps.map((step) => ({
78	    premium: quotePremium((step as QuoteStep).items),
79	  })),
80	});
